


export type UpdateSubscriptionOfferRequest = { /** minItems: 1. maxItems: 12. */ "billing_interval_options"?: Array<{ "billing_interval": "daily" | "weekly" | "monthly" | "yearly" | (string & {}); /** Format: int32. minimum: 1. maximum: 365. */ "billing_interval_count": number; }>; /** The version read before editing. A mismatch returns SUBSCRIPTION_OFFER_VERSION_CONFLICT. Use an exact numeric string, not a floating-point number. Format: uint64. minimum: 1. */ "expected_version"?: string; /** Caller-owned metadata. Omit this field to leave metadata unchanged. Send an object to merge by key, set a key to null to remove it, or set metadata to null to clear all metadata. An empty object makes no change. Empty strings are stored. Keys starting with flint_ are reserved and cannot be written through the public API. */ "metadata"?: Record<string, string | null> | null; /** minLength: 1. maxLength: 255. */ "name"?: string; /** Catalog targets for new signups. At least one product or variant is required. maxItems: 100. */ "product_ids"?: Array<string>; /** An active promotion with forever recurrence. On PATCH, null removes the discount for new signups; omission keeps it. */ "promotion_id"?: string | null; "status"?: "active" | "inactive" | (string & {}); /** Delivery methods offered at signup. An empty array uses the store's checkout defaults. Existing subscriptions keep their selected method. maxItems: 25. */ "subscription_delivery_method_ids"?: Array<string>; /** Catalog targets for new signups. At least one product or variant is required. maxItems: 100. */ "variant_ids"?: Array<string>; };
